def run(command, cwd=None, env=None, quiet=False):
    command = [str(item) for item in command]
    print("\n>>>", " ".join(command))
    process = subprocess.Popen(
        command,
        cwd=str(cwd) if cwd else None,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        errors="replace",
        bufsize=1,
    )
    lines = []
    for line in process.stdout:
        lines.append(line)
        if not quiet:
            print(line, end="")
    code = process.wait()
    if code:
        if quiet:
            print("".join(lines[-220:]))
        raise RuntimeError(
            f"Command failed with exit code {code}: {' '.join(command)}"
        )
    return lines


def file_digest(path, algorithm="sha256"):
    digest = hashlib.new(algorithm)
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def verify_arm64_elf(path):
    header = path.read_bytes()[:20]
    if header[:4] != b"\x7fELF":
        raise RuntimeError(f"Not an ELF binary: {path}")
    machine = int.from_bytes(header[18:20], "little")
    if machine != 183:
        raise RuntimeError(f"Not an ARM64 ELF binary: {path}")


