print("[7/9] Configuring Buildozer to reuse the verified NDK...")
spec_path = PROJECT_DIR / "buildozer.spec"
portable_spec = spec_path.read_text(encoding="utf-8")
if "android.ndk_path" in portable_spec:
    raise RuntimeError("The portable buildozer.spec unexpectedly contains android.ndk_path")
section_marker = "\n[buildozer]\n"
if section_marker not in portable_spec:
    raise RuntimeError("buildozer.spec is missing the [buildozer] section")
configured_spec = portable_spec.replace(
    section_marker,
    f"\nandroid.ndk_path = {NDK_DIR}\n\n[buildozer]\n",
    1,
)
spec_path.write_text(configured_spec, encoding="utf-8")

print("[8/9] Building the ARM64 debug APK. The first build can take 10–30 minutes...")
if build_env.get("VIRTUAL_ENV") != str(BUILD_VENV):
    raise RuntimeError("VIRTUAL_ENV was not exported to Buildozer")
build_log = PROJECT_DIR / "build.log"
process = subprocess.Popen(
    [venv_buildozer, "android", "debug"],
    cwd=str(PROJECT_DIR),
    env=build_env,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
    errors="replace",
    bufsize=1,
)
lines = []
with build_log.open("w", encoding="utf-8") as log:
    for line in process.stdout:
        lines.append(line)
        log.write(line)
        log.flush()
        if (
            line.startswith("#")
            or any(marker in line for marker in (
                "[INFO]", "[WARNING]", "[ERROR]", "BUILD SUCCESSFUL",
                "BUILD FAILED", "FAILURE:", "APK",
            ))
        ):
            print(line, end="")
